import{_ as r,C as s,o as a,c as l,a2 as u,b as c,w as i,a as o,E as d,a3 as p,j as t}from"./chunks/framework.CRkTBNIT.js";const $=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),m={name:"system-design/14.1-requirements-and-estimation.md"};function h(g,e,f,y,b,q){const n=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=u('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="_1-functional-non-functional-requirements" tabindex="-1">1. Functional &amp; Non-Functional Requirements <a class="header-anchor" href="#_1-functional-non-functional-requirements" aria-label="Permalink to &quot;1. Functional &amp; Non-Functional Requirements&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ul><li>Ingest notification requests across 5 channels (Email, SMS, Webhook, Push, In-App).</li><li>Enforce strict idempotency via client-provided keys to guarantee no duplicate deliveries.</li><li>Schedule delayed jobs for future dispatch (<code>run_at</code>).</li><li>Support multi-tier priority scheduling: URGENT, HIGH, NORMAL, LOW.</li><li>Enforce user preferences, category opt-outs, and timezone-aware quiet hours.</li><li>Provide resilience through exponential backoff retries, provider fallback, and dead-letter queue (DLQ) replay.</li></ul><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ul><li><strong>High Availability</strong>: 99.95% uptime for the ingestion API.</li><li><strong>Low Latency</strong>: Sub-second dispatch for URGENT (OTP) alerts; p99 API ingress &lt; 50ms.</li><li><strong>Durability</strong>: Zero message loss once acknowledged with HTTP 202.</li><li><strong>Auditability</strong>: Complete forensic trace of all delivery attempts and administrative actions.</li></ul><hr><h2 id="_2-capacity-estimation-10-million-notifications-day" tabindex="-1">2. Capacity Estimation (10 Million Notifications / Day) <a class="header-anchor" href="#_2-capacity-estimation-10-million-notifications-day" aria-label="Permalink to &quot;2. Capacity Estimation (10 Million Notifications / Day)&quot;">​</a></h2><p>Let us calculate capacity for a production scale of <strong>10,000,000 notifications per day</strong>.</p><h3 id="request-throughput-rps" tabindex="-1">Request Throughput (RPS) <a class="header-anchor" href="#request-throughput-rps" aria-label="Permalink to &quot;Request Throughput (RPS)&quot;">​</a></h3><p>$$\\text{Average RPS} = \\frac{10,000,000 \\text{ messages}}{86,400 \\text{ seconds}} \\approx 116 \\text{ requests/sec}$$ $$\\text{Peak RPS (3x multiplier)} = 116 \\times 3 \\approx 350 \\text{ requests/sec}$$ $$\\text{Marketing Blast Spike (10x)} \\approx 1,200 \\text{ requests/sec}$$</p><h3 id="storage-calculations" tabindex="-1">Storage Calculations <a class="header-anchor" href="#storage-calculations" aria-label="Permalink to &quot;Storage Calculations&quot;">​</a></h3><ul><li>Average payload size (recipient, subject, body, metadata): <strong>1 KB</strong></li><li>Daily storage for notifications: $$10,000,000 \\times 1 \\text{ KB} = 10,000,000 \\text{ KB} \\approx 10 \\text{ GB/day}$$</li><li>Delivery attempt records (avg 1.2 attempts per message @ 200 bytes): $$10,000,000 \\times 1.2 \\times 200 \\text{ bytes} \\approx 2.4 \\text{ GB/day}$$</li><li>Total storage growth per year: $$(10 \\text{ GB} + 2.4 \\text{ GB}) \\times 365 \\approx 4.5 \\text{ TB/year}$$</li></ul><h3 id="bandwidth-calculations" tabindex="-1">Bandwidth Calculations <a class="header-anchor" href="#bandwidth-calculations" aria-label="Permalink to &quot;Bandwidth Calculations&quot;">​</a></h3><ul><li>Ingress bandwidth (avg 116 req/sec @ 1 KB): $$116 \\times 1 \\text{ KB} \\approx 116 \\text{ KB/sec} \\approx 0.93 \\text{ Mbps}$$</li><li>Peak egress bandwidth (350 req/sec @ 1.5 KB payload to SendGrid/Twilio): $$350 \\times 1.5 \\text{ KB} \\approx 525 \\text{ KB/sec} \\approx 4.2 \\text{ Mbps}$$</li></ul>',15)),(a(),c(p,null,{default:i(()=>[d(n,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Ingress%5B%22350%20Peak%20RPS%20(0.93%20Mbps)%22%5D%20--%3E%20API%5B%22FastAPI%20Replicas%22%5D%0A%20%20%20%20API%20--%3E%20Storage%5B%2212.4%20GB%2FDay%20Persistence%22%5D%0A%20%20%20%20API%20--%3E%20Egress%5B%224.2%20Mbps%20Outbound%20Vendor%20Egress%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"_3-say-it-out-loud",tabindex:"-1"},[o("3. Say It Out Loud "),t("a",{class:"header-anchor",href:"#_3-say-it-out-loud","aria-label":'Permalink to "3. Say It Out Loud"'},"​")],-1)),e[4]||(e[4]=t("blockquote",null,[t("p",null,'"For our capacity planning, I modeled the platform for 10 million notifications daily, which translates to an average throughput of 116 requests per second with marketing blast spikes reaching 1,200 RPS. At an average payload size of one kilobyte, the platform accumulates approximately 12.4 gigabytes of data daily across notifications and delivery attempt ledgers, totaling about 4.5 terabytes annually. Our network egress bandwidth peaks at roughly 4.2 megabits per second. To prevent database exhaustion at this volume, our architecture uses database table partitioning with automated 90-day cold-storage archiving."')],-1))])}const P=r(m,[["render",h]]);export{$ as __pageData,P as default};
